// AccountsTable.java — table with BEFORE-UPDATE and AFTER-UPDATE triggers
package com.nbi.db;

import java.util.*;

public class AccountsTable {
    private final Map<String,Double> balances = new HashMap<>();
    private final List<String> auditLog = new ArrayList<>(); // audit history table

    public void seed(String acct, double bal) { balances.put(acct, bal); }
    public List<String> auditLog() { return auditLog; }
    public double balance(String acct) { return balances.get(acct); }

    // UPDATE accounts SET balance = :new WHERE account = :acct
    public void updateBalance(String acct, double newBalance) {
        Double oldBalance = balances.get(acct); // OLD row image
        if (oldBalance == null) throw new TriggerException("no such account");

        // ---- BEFORE UPDATE trigger: validate / can reject or modify NEW ----
        beforeUpdate(acct, oldBalance, newBalance);

        // ---- actual row write ----
        balances.put(acct, newBalance);

        // ---- AFTER UPDATE trigger: react (audit), cannot change the row ----
        afterUpdate(acct, oldBalance, newBalance);
    }

    // BEFORE: runs before write; may reject (RAISE) or adjust NEW values.
    private void beforeUpdate(String acct, double oldBal, double newBal) {
        if (newBal < 0) {
            // reject the whole operation -> transaction would roll back
            throw new TriggerException(
                "BEFORE UPDATE: balance for " + acct + " cannot go negative (" + newBal + ")");
        }
    }

    // AFTER: runs after write; records immutable audit with OLD + NEW.
    private void afterUpdate(String acct, double oldBal, double newBal) {
        auditLog.add(String.format("AUDIT %s: %.2f -> %.2f", acct, oldBal, newBal));
    }
}
