// Demo.java — shows automatic BEFORE validation and AFTER auditing
package com.nbi.db;

public class Demo {
    public static void main(String[] args) {
        AccountsTable accounts = new AccountsTable();
        accounts.seed("A100", 5000);

        // Valid update: BEFORE passes, row written, AFTER audits automatically.
        accounts.updateBalance("A100", 7000);
        System.out.println("A100 balance after valid update = " + accounts.balance("A100"));

        // Invalid update: BEFORE trigger rejects, no write, no audit row added.
        try {
            accounts.updateBalance("A100", -200);
        } catch (TriggerException e) {
            System.out.println("Rejected: " + e.getMessage());
        }
        System.out.println("A100 balance unchanged after reject = " + accounts.balance("A100"));

        System.out.println("Audit trail (written automatically by AFTER trigger):");
        accounts.auditLog().forEach(line -> System.out.println("  " + line));
    }
}
